import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Loader from './Loader';
import '../styles/NewsPage.css';

const NewsPage = () => {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingSources, setLoadingSources] = useState(true);
  const [activeFilter, setActiveFilter] = useState('all');
  const [activeSource, setActiveSource] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [error, setError] = useState(null);
  const [sources, setSources] = useState([]);
  const [categories, setCategories] = useState([
    { id: 'all', name: 'Semua' },
    { id: 'general', name: 'Umum' },
  ]);

  // Fetch available news sources when the component mounts
  useEffect(() => {
    const fetchSources = async () => {
      try {
        const response = await axios.get('http://localhost:5000/news/sources');
        if (response.data && response.data.sources) {
          setSources(response.data.sources);
          
          // Set first source as active by default
          if (response.data.sources.length > 0 && !activeSource) {
            setActiveSource(response.data.sources[0].id);
          }
        }
      } catch (error) {
        console.error('Error fetching news sources:', error);
      } finally {
        setLoadingSources(false);
      }
    };

    fetchSources();
  }, []);

  // Update categories when source changes
  useEffect(() => {
    if (activeSource && sources.length > 0) {
      const sourceData = sources.find(s => s.id === activeSource);
      if (sourceData && sourceData.categories) {
        // Always include 'all' category
        const newCategories = [
          { id: 'all', name: 'Semua' },
          ...sourceData.categories.map(cat => ({
            id: cat,
            name: cat.charAt(0).toUpperCase() + cat.slice(1)
          }))
        ];
        setCategories(newCategories);
        setActiveFilter('all'); // Reset category when source changes
      }
    }
  }, [activeSource, sources]);

  // Fetch news data when component mounts or filters change
  useEffect(() => {
    const fetchNews = async () => {
      if (loadingSources) return; // Wait until sources are loaded
      
      setLoading(true);
      setError(null);
      
      try {
        // Build the API endpoint based on the active filters
        let endpoint = 'http://localhost:5000/news';
        const params = {};
        
        if (activeSource) {
          params.source = activeSource;
        }
        
        if (activeFilter !== 'all') {
          params.category = activeFilter;
        }
        
        console.log('Fetching news with params:', params);
        const response = await axios.get(endpoint, { params });
        
        if (response.data && Array.isArray(response.data)) {
          // Ensure all necessary fields exist and format dates
          const processedNews = response.data.map(item => ({
            ...item,
            title: item.title || 'Tidak ada judul',
            description: item.description || item.title || 'Tidak ada deskripsi',
            url: item.url || '#',
            urlToImage: item.urlToImage || null,
            publishedAt: item.publishedAt || new Date().toISOString(),
            source: item.source || { name: 'Unknown' },
            category: item.category || 'general'
          }));
          
          // Sort news by date (newest first)
          const sortedNews = processedNews.sort((a, b) => 
            new Date(b.publishedAt) - new Date(a.publishedAt)
          );
          
          setNews(sortedNews);
        } else {
          console.warn('API did not return an array:', response.data);
          setNews([]);
        }
      } catch (error) {
        console.error('Error fetching news:', error);
        setError('Gagal memuat berita. Silakan coba lagi nanti.');
        // Provide fallback data in case API fails
        setNews(sampleNewsData);
      } finally {
        setLoading(false);
      }
    };

    fetchNews();
  }, [activeFilter, activeSource, loadingSources]);

  // Filter news based on search term
  const filteredNews = news.filter(item => {
    // Only filter by search term since category filtering is now handled by API
    return !searchTerm || 
      (item.title && item.title.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (item.description && item.description.toLowerCase().includes(searchTerm.toLowerCase()));
  });

  // Format date to locale string
  const formatDate = (dateString) => {
    try {
      const options = { year: 'numeric', month: 'long', day: 'numeric' };
      return new Date(dateString).toLocaleDateString('id-ID', options);
    } catch (error) {
      console.error('Error formatting date:', dateString, error);
      return 'Tanggal tidak tersedia';
    }
  };

  // Handle category filter change
  const handleFilterChange = (categoryId) => {
    setActiveFilter(categoryId);
  };

  // Handle source filter change
  const handleSourceChange = (sourceId) => {
    setActiveSource(sourceId);
  };

  // Handle search input change
  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  // Handle search form submission
  const handleSearchSubmit = (e) => {
    e.preventDefault();
    // Additional search functionality could be added here
  };

  return (
    <div className="news-container">
      <section className="news-hero-section">
        <div className="news-hero-content">
          <h1>Berita & Analisis Pasar</h1>
          <p>Dapatkan informasi terkini seputar pasar modal, ekonomi, dan bisnis</p>
        </div>
      </section>

      <section className="news-filter-section">
        <form className="news-search" onSubmit={handleSearchSubmit}>
          <input
            type="text"
            placeholder="Cari berita..."
            value={searchTerm}
            onChange={handleSearchChange}
            className="search-input"
          />
          <button type="submit" className="search-button">
            <i className="search-icon">🔍</i>
          </button>
        </form>

        {/* Source filters */}
        {loadingSources ? (
          <div className="source-loading">Memuat sumber berita...</div>
        ) : (
          <div className="source-filters">
            <div className="filter-section-title">Sumber Berita:</div>
            <div className="filter-buttons">
              {sources.map(source => (
                <button
                  key={source.id}
                  className={`source-filter-btn ${activeSource === source.id ? 'active' : ''}`}
                  onClick={() => handleSourceChange(source.id)}
                >
                  {source.name}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Category filters */}
        <div className="category-filters">
          <div className="filter-section-title">Kategori:</div>
          <div className="filter-buttons">
            {categories.map(category => (
              <button
                key={category.id}
                className={`category-filter-btn ${activeFilter === category.id ? 'active' : ''}`}
                onClick={() => handleFilterChange(category.id)}
              >
                {category.name}
              </button>
            ))}
          </div>
        </div>
      </section>

      <section className="news-content-section">
        <div className="section-header">
          <h2 className="section-title">
            {activeSource && sources.find(s => s.id === activeSource)?.name} - {
              activeFilter === 'all' 
                ? 'Semua Berita' 
                : `Kategori ${categories.find(c => c.id === activeFilter)?.name || ''}`
            }
          </h2>
          <div className="section-divider"></div>
        </div>

        {error && (
          <div className="error-message">
            <p>{error}</p>
          </div>
        )}

        {loading ? (
          <div className="center-loader">
            <Loader />
          </div>
        ) : filteredNews.length > 0 ? (
          <div className="news-grid">
            {filteredNews.map((article, index) => (
              <div className="news-card" key={index}>
                <div className="news-card-gradient"></div>
                {article.urlToImage && (
                  <div 
                    className="news-image" 
                    style={{ 
                      backgroundImage: `url(${article.urlToImage})`,
                      backgroundSize: 'cover',
                      backgroundPosition: 'center',
                      backgroundRepeat: 'no-repeat'
                    }}
                  />
                )}
                <div className="news-card-content">
                  <div className="news-meta">
                    <span className="news-category">{article.category || 'Umum'}</span>
                    <span className="news-date">{formatDate(article.publishedAt)}</span>
                  </div>
                  <h2 className="news-title">{article.title}</h2>
                  <p className="news-description">{article.description}</p>
                  <div className="news-source">
                    {article.source && article.source.name && (
                      <span>Sumber: {article.source.name}</span>
                    )}
                    {article.related && (
                      <span className="news-related">Terkait: {article.related}</span>
                    )}
                  </div>
                  <a 
                    href={article.url} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="read-more-btn"
                  >
                    Baca Selengkapnya
                  </a>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="no-news-found">
            <h3>Tidak ada berita yang ditemukan</h3>
            <p>Coba ubah filter atau kata kunci pencarian Anda</p>
          </div>
        )}
      </section>
    </div>
  );
};

